DataCalcInsightTemplate.expression:
SELECT
  SUM({Source:Reservation__dlm}.{Source_Field:Total_Price__c}) AS {CI_Target_Field:clv__c},
  COUNT({Source:Reservation__dlm}.{Source_Field:Reservation_ID__c}) AS {CI_Target_Field:reservation_by_customer__c},
  {Source:UnifiedssotIndividualCcid__dlm}.{Source_Field:ssot__Id__c} AS {CI_Target_Field:person__c}
FROM {Source:Reservation__dlm}
  JOIN {Source:ssot__Individual__dlm}
    ON ({Source:Reservation__dlm}.{Source_Field:Contact_ID__c} = {Source:ssot__Individual__dlm}.{Source_Field:ssot__Id__c} AND {Source:Reservation__dlm}.{Source_Field:KQ_Contact_ID__c} = {Source:ssot__Individual__dlm}.{Source_Field:KQ_Id__c})
  JOIN {Source:UnifiedLinkssotIndividualCcid__dlm}
    ON ({Source:ssot__Individual__dlm}.{Source_Field:ssot__Id__c} = {Source:UnifiedLinkssotIndividualCcid__dlm}.{Source_Field:SourceRecordId__c} AND {Source:ssot__Individual__dlm}.{Source_Field:KQ_Id__c} = {Source:UnifiedLinkssotIndividualCcid__dlm}.{Source_Field:KQ_SourceRecordId__c})
  JOIN {Source:UnifiedssotIndividualCcid__dlm}
    ON ({Source:UnifiedLinkssotIndividualCcid__dlm}.{Source_Field:UnifiedRecordId__c} = {Source:UnifiedssotIndividualCcid__dlm}.{Source_Field:ssot__Id__c})
GROUP BY {Source_Field:person__c}
